Lemma u64s_read : forall m A ws (i : Z) w a,
  bytes_at asegs m A (u64s ws) -> nth_error ws (Z.to_nat i) = Some w -> 0 <= i -> a = wa (A + 8 * i) ->
  ov_read_bytes asegs m a 8 = Some (le8 w).
Proof.
